export const JOINTS=['Hips','Spine','Head','LeftArm','LeftForeArm','LeftHand','RightArm','RightForeArm','RightHand','LeftUpLeg','LeftLeg','LeftFoot','RightUpLeg','RightLeg','RightFoot'];
export const LABELS=['골반','가슴','머리','왼쪽 어깨','왼쪽 팔꿈치','왼손','오른쪽 어깨','오른쪽 팔꿈치','오른손','왼쪽 골반','왼쪽 무릎','왼쪽 발목','오른쪽 골반','오른쪽 무릎','오른쪽 발목'];
export function samplePose(action,frame){const keys=[...action.keys].sort((a,b)=>a.frame-b.frame);const a=keys.filter(k=>k.frame<=frame).at(-1)||keys[0],b=keys.find(k=>k.frame>frame)||a;let t=a===b?0:(frame-a.frame)/(b.frame-a.frame);if(a.ease==='hold')t=0;if(a.ease==='smooth')t=t*t*(3-2*t);return Object.fromEntries(JOINTS.map(n=>[n,a.pose[n].map((v,i)=>v+(b.pose[n][i]-v)*t)]));}
export function validateProject(p){if(p?.version!==1||!Array.isArray(p.actions)||!p.actions.length||p.actions.length>100)throw Error('지원하는 동작 파일이 아닙니다. 이 편집기에서 내보낸 JSON을 선택하세요.');for(const a of p.actions){if(typeof a.name!=='string'||a.name.length>100||!Number.isInteger(a.frames)||a.frames<2||a.frames>240||!Number.isFinite(a.fps)||a.fps<1||a.fps>60||!Array.isArray(a.keys)||!a.keys.length||a.keys.length>a.frames)throw Error('동작 이름, 프레임 수 또는 키프레임을 확인하세요.');const seen=new Set();for(const k of a.keys){if(!Number.isInteger(k.frame)||k.frame<0||k.frame>=a.frames||seen.has(k.frame)||!['linear','smooth','hold'].includes(k.ease))throw Error('키프레임 위치 또는 보간 방식이 잘못되었습니다.');seen.add(k.frame);for(const n of JOINTS)if(!Array.isArray(k.pose?.[n])||k.pose[n].length!==3||!k.pose[n].every(v=>Number.isFinite(v)&&Math.abs(v)<=100))throw Error('관절 좌표가 잘못되었습니다.');}}return p;}
